{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "In fasting subjects, racemic propranolol had a mean absolute oral bioavailability of 27.2%, above the 20% threshold, showing that even drugs with substantial first-pass metabolism can meet the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Bornaprolol absolute oral bioavailability was 46% ± 9% at 120 mg in healthy volunteers, supporting high F for a lipophilic cyclic alcohol/ether-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Nipradilol, a beta-blocker with multiple hydroxyls and a cyclic ether, had F = 32% ± 3% in younger subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pethidine absolute oral bioavailability was 0.52 in healthy volunteers, supporting high F for a moderately lipophilic drug with first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Warfarin, an acidic drug, has nearly complete oral bioavailability, demonstrating that acidic molecules can be very well absorbed when sufficiently lipophilic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Nicainoprol oral bioavailability averaged 69.4% in humans, supporting high F for a fused-ring drug with moderate lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Perindoprilat, a highly polar diacid metabolite, had F = 19% ± 7% after oral prodrug, slightly below the threshold; this is the only sub-20% value and is unlikely to transfer to the more lipophilic monocarboxylic acid query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic carboxylic acid with a long alkyl chain, multiple rings, and hydroxyls. High-transfer human absolute bioavailability data for diverse drugs—propranolol (~27%), bornaprolol (22–46%), nipradilol (32–52%), pethidine (~50%), warfarin (near complete), and nicainoprol (~70%)—consistently support F ≥ 20%. The only sub-20% value (perindoprilat, 19%) comes from a polar diacid metabolite and is not representative of the query's more lipophilic acid scaffold. Therefore, the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule; prediction relies on analogue evidence.",
    "The query's specific first-pass metabolism (e.g., glucuronidation of the phenoxyacetic acid or hydroxyls) and transporter involvement are not directly assessed.",
    "The only sub-20% analogue (perindoprilat) is a polar diacid, leaving some uncertainty about how the query's carboxylic acid and hydroxyls affect permeability and metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

